import GridBackground from "@/components/grid-background";
import LandingNavbar from "@/components/navbar";
import Footer from "@/components/footer";
import ImageWithFallback from "@/components/image-with-fallback";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { getPublicUrl } from "@/utils/url";
import { trpc } from "@/utils/trpc";
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useQuery } from "@tanstack/react-query";
import { format } from "date-fns";
import { id as idLocale } from "date-fns/locale";
import { Calendar, ArrowLeft, ChevronLeft, ChevronRight } from "lucide-react";
import { pageHead } from "@/utils/page-head";
import type { MediaPublications } from "@tepian-k3/types/platform/media-publications.types";
import z from "zod";
import { cn } from "@/lib/utils";

export const Route = createFileRoute("/media-dan-publikasi/")({
  validateSearch: z.object({
    page: z.number().int().min(1).default(1),
    category: z.string().optional(),
    title: z.string().default(""),
  }),
  component: MediaListPage,
  head: () => pageHead("Media dan Publikasi - Balai K3 Samarinda"),
});

/**
 * Komponen halaman list portal publik Media dan Publikasi.
 * Menampilkan item teratas sebagai Featured Banner premium, dan item berikutnya
 * dalam layout Grid Cards dengan soft blue shadows dan pagination offset.
 *
 * @returns {JSX.Element} Elemen halaman portal publik Media dan Publikasi.
 */
function MediaListPage() {
  const navigate = useNavigate();
  const searchParams = Route.useSearch();
  const { page, category, title } = searchParams;

  const perPage = 10; // 1 featured banner + 9 cards on page 1

  const { data, isLoading, isError } = useQuery(
    trpc.platform.mediaPublications.getPublicOffsetPaginatedMedia.queryOptions({
      page,
      perPage,
      title,
      category,
      sort: [{ id: "publishedAt", desc: true }],
    }),
  );

  const handlePageChange = (newPage: number) => {
    navigate({
      to: "/media-dan-publikasi",
      search: {
        ...searchParams,
        page: newPage,
      },
    });
  };

  const handleCategoryFilter = (newCategory: string | undefined) => {
    navigate({
      to: "/media-dan-publikasi",
      search: {
        ...searchParams,
        page: 1,
        category: newCategory,
      },
    });
  };

  const handleSearchChange = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formEl = e.currentTarget;
    const formData = new FormData(formEl);
    const searchVal = formData.get("search") as string;
    navigate({
      to: "/media-dan-publikasi",
      search: {
        ...searchParams,
        page: 1,
        title: searchVal,
      },
    });
  };

  const mediaList = (data?.data ?? []) as MediaPublications[];
  const pageCount = data?.pageCount ?? 0;

  // Split featured and grid on page 1
  const featuredItem = page === 1 ? mediaList[0] : null;
  const gridItems = page === 1 ? mediaList.slice(1) : mediaList;

  return (
    <div className="flex min-h-screen w-full flex-col overflow-x-hidden overflow-y-auto bg-[#FAFAFA] dark:bg-neutral-950">
      <LandingNavbar />

      {/* Hero Header */}
      <section className="relative flex h-[240px] flex-col items-center justify-center bg-[#1061D6] px-4 text-center sm:px-6 md:px-10">
        <div className="pointer-events-none absolute inset-0 overflow-hidden opacity-20">
          <GridBackground />
        </div>
        <div className="relative z-10 flex flex-col items-center gap-3">
          <h1 className="font-['Poppins'] text-3xl font-bold text-white md:text-5xl">
            Media dan Publikasi
          </h1>
          <div className="h-1.5 w-48 rounded-[2px] bg-gradient-to-r from-[#AFCFFA] to-white" />
          <p className="mt-1 max-w-2xl text-sm font-medium text-white/95 md:text-base">
            Informasi, berita terbaru, dan publikasi resmi dari Balai K3
            Samarinda
          </p>
        </div>
      </section>

      {/* Back Button, Search & Category Filters */}
      <div className="container mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
        <div className="flex flex-col gap-6 md:flex-row md:items-center md:justify-between">
          <Button
            variant="ghost"
            className="w-fit gap-2 text-neutral-600 hover:text-[#1061D6] dark:text-neutral-400"
            onClick={() => navigate({ to: "/ppid" })}
          >
            <ArrowLeft className="size-4" />
            Kembali ke Portal PPID
          </Button>

          <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
            {/* Search Bar */}
            <form
              onSubmit={handleSearchChange}
              className="relative flex items-center"
            >
              <input
                type="text"
                name="search"
                defaultValue={title}
                placeholder="Cari artikel..."
                className="h-10 w-full rounded-xl border border-neutral-200 bg-white px-4 pr-10 text-sm focus:border-[#1061D6] focus:outline-none sm:w-64 dark:border-neutral-800 dark:bg-neutral-900"
              />
              <button
                type="submit"
                className="absolute right-3 text-neutral-400 hover:text-[#1061D6]"
              >
                <svg
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <circle cx="11" cy="11" r="8" />
                  <path d="m21 21-4.3-4.3" />
                </svg>
              </button>
            </form>

            {/* Category Select Filters */}
            <div className="flex gap-2">
              <Button
                variant={category === undefined ? "default" : "outline"}
                className={cn(
                  "h-10 rounded-xl px-4 text-xs font-semibold",
                  category === undefined && "bg-[#1061D6] text-white",
                )}
                onClick={() => handleCategoryFilter(undefined)}
              >
                Semua
              </Button>
              <Button
                variant={category === "media" ? "default" : "outline"}
                className={cn(
                  "h-10 rounded-xl px-4 text-xs font-semibold",
                  category === "media" && "bg-[#1061D6] text-white",
                )}
                onClick={() => handleCategoryFilter("media")}
              >
                Media
              </Button>
              <Button
                variant={category === "publikasi" ? "default" : "outline"}
                className={cn(
                  "h-10 rounded-xl px-4 text-xs font-semibold",
                  category === "publikasi" && "bg-[#1061D6] text-white",
                )}
                onClick={() => handleCategoryFilter("publikasi")}
              >
                Publikasi
              </Button>
            </div>
          </div>
        </div>

        {isLoading && (
          <div className="mt-8 space-y-8">
            <Skeleton className="h-[400px] w-full rounded-[18px]" />
            <div className="grid grid-cols-1 gap-8 md:grid-cols-2 lg:grid-cols-3">
              {Array.from({ length: 6 }).map((_, idx) => (
                <Skeleton key={idx} className="h-96 w-full rounded-[20px]" />
              ))}
            </div>
          </div>
        )}

        {isError && (
          <div className="mt-8 flex h-64 flex-col items-center justify-center text-center">
            <p className="text-lg font-semibold text-neutral-600">
              Gagal memuat media dan publikasi
            </p>
            <Button
              className="mt-4 bg-[#1061D6]"
              onClick={() => window.location.reload()}
            >
              Coba Lagi
            </Button>
          </div>
        )}

        {!isLoading && !isError && mediaList.length === 0 && (
          <div className="mt-8 flex h-64 flex-col items-center justify-center text-center text-neutral-500">
            <p className="text-lg">
              Tidak ada media dan publikasi yang ditemukan
            </p>
          </div>
        )}

        {!isLoading && !isError && mediaList.length > 0 && (
          <div className="mt-8 space-y-12">
            {/* Featured Banner (Page 1 Only) */}
            {featuredItem && (
              <div
                className="group relative flex h-[400px] w-full cursor-pointer flex-col justify-end overflow-hidden rounded-[18px] shadow-lg md:h-[550px] lg:h-[646px]"
                onClick={() =>
                  navigate({
                    to: "/media-dan-publikasi/$newsId",
                    params: { newsId: featuredItem.id },
                  })
                }
              >
                <div className="absolute inset-0">
                  <ImageWithFallback
                    src={getPublicUrl(featuredItem.imageUrl ?? "")}
                    alt={featuredItem.title}
                    className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-103"
                    fallbackClassName="h-full w-full flex items-center justify-center bg-neutral-100 text-neutral-400"
                  />
                  {/* Figma Gradient overlay */}
                  <div className="absolute inset-0 bg-gradient-to-t from-black/95 via-black/50 to-transparent" />
                </div>

                <div className="relative z-10 flex max-w-4xl flex-col gap-4 p-6 text-left md:p-12">
                  <span className="w-fit rounded-full bg-[#1061D6] px-3.5 py-1 text-xs font-extrabold tracking-wide text-white uppercase">
                    {featuredItem.category}
                  </span>
                  <h2 className="font-['Poppins'] text-xl leading-tight font-medium text-white group-hover:underline md:text-3xl lg:text-[32px]">
                    {featuredItem.title}
                  </h2>
                  <p className="line-clamp-2 text-sm font-medium text-white/90 md:text-lg lg:text-[20px]">
                    {featuredItem.description ||
                      featuredItem.content
                        .replace(/<[^>]*>/g, "")
                        .slice(0, 180)}
                  </p>
                  <div className="mt-2 flex items-center gap-2">
                    <span className="text-xs text-neutral-300 md:text-sm">
                      {featuredItem.publishedAt
                        ? format(
                            new Date(featuredItem.publishedAt),
                            "dd MMMM yyyy",
                            {
                              locale: idLocale,
                            },
                          )
                        : "-"}
                    </span>
                    <span className="text-neutral-400">•</span>
                    <span className="text-xs text-neutral-300 md:text-sm">
                      {featuredItem.publisher}
                    </span>
                  </div>
                  <Button className="mt-2 w-fit rounded-xl bg-white font-semibold text-[#1061D6] hover:bg-neutral-100">
                    Selengkapnya
                  </Button>
                </div>
              </div>
            )}

            {/* Card Grid */}
            {gridItems.length > 0 && (
              <div className="space-y-6">
                {page === 1 && (
                  <h2 className="text-left font-['Poppins'] text-2xl leading-8 font-semibold tracking-tight text-neutral-700">
                    Media dan Publikasi Terbaru
                  </h2>
                )}
                <div className="grid grid-cols-1 gap-8 md:grid-cols-2 lg:grid-cols-3">
                  {gridItems.map((item) => (
                    <Card
                      key={item.id}
                      className="group flex h-full cursor-pointer flex-col overflow-hidden rounded-[20px] border border-transparent bg-white shadow-[0px_0px_100px_-2px_rgba(16,97,214,0.14)] transition-all duration-300 hover:shadow-lg dark:bg-neutral-900"
                      onClick={() =>
                        navigate({
                          to: "/media-dan-publikasi/$newsId",
                          params: { newsId: item.id },
                        })
                      }
                    >
                      <div className="relative h-56 w-full overflow-hidden">
                        <ImageWithFallback
                          src={getPublicUrl(item.imageUrl ?? "")}
                          alt={item.title}
                          className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                          fallbackClassName="h-full w-full flex items-center justify-center bg-neutral-100 text-neutral-400"
                        />
                        <span className="absolute top-4 left-4 rounded-full bg-[#1061D6] px-3.5 py-1 text-[10px] font-extrabold tracking-wide text-white uppercase">
                          {item.category}
                        </span>
                      </div>
                      <CardContent className="flex flex-1 flex-col gap-3 p-6 text-left">
                        <div className="flex items-center gap-2 text-xs font-medium text-neutral-400">
                          <Calendar className="size-3.5" />
                          <span>
                            {item.publishedAt
                              ? format(
                                  new Date(item.publishedAt),
                                  "dd MMMM yyyy",
                                  {
                                    locale: idLocale,
                                  },
                                )
                              : "-"}
                          </span>
                        </div>
                        <h3 className="line-clamp-2 font-['Poppins'] text-base font-semibold text-neutral-800 transition-colors group-hover:text-[#1061D6] group-hover:underline md:text-lg dark:text-neutral-100">
                          {item.title}
                        </h3>
                        <p className="line-clamp-3 flex-1 text-sm leading-relaxed text-[#4D4D4D] dark:text-neutral-400">
                          {item.description ||
                            item.content.replace(/<[^>]*>/g, "").slice(0, 120) +
                              "..."}
                        </p>
                        <span className="mt-2 w-fit text-sm font-semibold text-[#1061D6] group-hover:underline">
                          Baca selengkapnya →
                        </span>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            )}

            {/* Offset Pagination Controls */}
            {pageCount > 1 && (
              <div className="flex items-center justify-center gap-2 py-8">
                <Button
                  variant="outline"
                  size="icon"
                  className="rounded-xl border-neutral-200"
                  disabled={page === 1}
                  onClick={() => handlePageChange(page - 1)}
                >
                  <ChevronLeft className="size-4" />
                </Button>
                {Array.from({ length: pageCount }).map((_, idx) => {
                  const pNum = idx + 1;
                  return (
                    <Button
                      key={pNum}
                      variant={page === pNum ? "default" : "outline"}
                      className={cn(
                        "h-10 w-10 rounded-xl text-sm font-semibold",
                        page === pNum
                          ? "bg-[#1061D6] text-white hover:bg-[#1061D6]"
                          : "border-neutral-200 text-neutral-600 hover:text-[#1061D6]",
                      )}
                      onClick={() => handlePageChange(pNum)}
                    >
                      {pNum}
                    </Button>
                  );
                })}
                <Button
                  variant="outline"
                  size="icon"
                  className="rounded-xl border-neutral-200"
                  disabled={page === pageCount}
                  onClick={() => handlePageChange(page + 1)}
                >
                  <ChevronRight className="size-4" />
                </Button>
              </div>
            )}
          </div>
        )}
      </div>

      <Footer />
    </div>
  );
}

